func ParseMakefileDecls(r io.Reader) (Decl, error) {
	raw := map[string][]string{}
	sc := bufio.NewScanner(r)
	var current string
	for sc.Scan() {
		line := sc.Text()
		if current == "" {
			name, rest, ok := declStart(line)
			if !ok { continue }
			current = name
			raw[current] = append(raw[current], fields(rest)...)
			if !strings.HasSuffix(strings.TrimRight(line, " \t"), `\`) { current = "" }
			continue
		}
		raw[current] = append(raw[current], fields(line)...)
		if !strings.HasSuffix(strings.TrimRight(line, " \t"), `\`) { current = "" }
	}
	if err := sc.Err(); err != nil { return Decl{}, fmt.Errorf("reading makefile: %w", err) }
	for _, name := range declBlocks[:3] { // RELEASE_IMAGES, AGENT_DEPLOY_SERVICES, RETAG_EXEMPT
		if _, ok := raw[name]; !ok {
			return Decl{}, fmt.Errorf("%s is not declared in the makefile — refusing to report on a release shape that was never read", name)
		}
	}
	d.ReleaseImages = raw["RELEASE_IMAGES"]
	d.AgentDeploy = toEntries(raw["AGENT_DEPLOY_SERVICES"])
	d.RetagExempt = toEntries(raw["RETAG_EXEMPT"])
	d.OwnLineage = toEntries(raw["OWN_LINEAGE"]) // optional; nil when absent
	return d, nil
}

func fields(s string) []string {
	if i := strings.Index(s, "#"); i >= 0 { s = s[:i] }
	s = strings.TrimRight(strings.TrimRight(s, " \t"), `\`)
	return strings.Fields(s) // Fields splits on tabs too — the live blocks are TAB-indented
}

func (e Entry) Image() string { if e.Qualifier != "" { return e.Qualifier }; return e.Service }

func (d Decl) InAnyReleasePath(service string) bool {
	if _, ok := lookup(d.AgentDeploy, service); ok { return true }
	_, ok := lookup(d.RetagExempt, service); return ok
}

func ScanOverlays(root string) ([]Pin, error) {
	servicesDir := filepath.Join(root, "deployments", "kustomize", "services")
	info, err := os.Stat(servicesDir)
	if err != nil {
		return nil, fmt.Errorf("cannot read %s: %w — refusing to report zero overlays when the tree was never opened", servicesDir, err)
	}
	if !info.IsDir() { return nil, fmt.Errorf("%s is not a directory", servicesDir) }
	for _, svcDir := range entries {
		prodRoot := filepath.Join(servicesDir, svcDir.Name(), "overlays", "production")
		if _, err := os.Stat(prodRoot); err != nil { continue } // base-only, applied by hand
		filepath.WalkDir(prodRoot, func(path string, d fs.DirEntry, err error) error {
			if err != nil { return err }
			if d.IsDir() || d.Name() != "kustomization.yaml" { return nil }
			raw, err := os.ReadFile(path)
			if err != nil { return fmt.Errorf("reading %s: %w", path, err) }
			if img, tag, ok := firstImage(string(raw)); ok {
				pins = append(pins, Pin{Service: svcDir.Name(), Image: img, Tag: tag, Path: rel})
			}
			return nil
		})
	}
	return pins, nil
}

// firstImage: block ends at the first non-indented non-blank line; the ELEMENT
// ends at the next "- " so a second image cannot overwrite the first; newName
// wins over name regardless of source order.
func firstImage(text string) (image, tag string, ok bool) {
	var name, newName string
	inImages, inFirst := false, false
	for _, line := range strings.Split(text, "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "#") { continue }
		if !inImages { if trimmed == "images:" { inImages = true }; continue }
		if trimmed != "" && !strings.HasPrefix(line, " ") && !strings.HasPrefix(line, "\t") { break }
		if strings.HasPrefix(trimmed, "- ") || trimmed == "-" {
			if inFirst { break }
			inFirst = true
			trimmed = strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
		}
		if !inFirst || trimmed == "" { continue }
		switch {
		case strings.HasPrefix(trimmed, "newName:"): newName = value(trimmed)
		case strings.HasPrefix(trimmed, "name:"):    name = value(trimmed)
		case strings.HasPrefix(trimmed, "newTag:"):  tag = value(trimmed)
		}
	}
	image = newName
	if image == "" { image = name }
	return image, tag, image != ""
}

func (p Pin) Bare(registry string) string {
	prefix := strings.TrimSuffix(registry, "/") + "/"
	if !strings.HasPrefix(p.Image, prefix) { return "" }
	return strings.TrimPrefix(p.Image, prefix)
}

func UncoveredOverlays(d Decl, pins []Pin, registry string) []Violation {
	var out []Violation
	for _, p := range pins {
		bare := p.Bare(registry)
		if bare == "" { continue } // not our image: ollama, postgres — not ours to roll
		if !d.HasReleaseImage(bare) {
			if e, ok := lookup(d.OwnLineage, p.Service); ok {
				if e.Qualifier == "" {
					out = append(out, Violation{Kind: KindExemptionUnreasoned, Service: p.Service,
						Detail: fmt.Sprintf("OWN_LINEAGE entry %q exempts it but names no target that retags it", e.Raw),
						Remedy: fmt.Sprintf("write it as '%s:<the make target that retags it>'.", p.Service)})
				}
				continue // exempt, deliberately and visibly
			}
			out = append(out, Violation{Kind: KindUnbuiltImage, Service: p.Service,
				Detail: fmt.Sprintf("pins %s, one of OUR images, in NO release path — nothing builds, pushes or retags it, so it freezes at %s for ever", p.Image, orNone(p.Tag)),
				Remedy: "add it to RELEASE_IMAGES and AGENT_DEPLOY_SERVICES in the commit that creates the service; or declare '<svc>:<its retag target>' in OWN_LINEAGE.",
				Source: p.Path})
			continue
		}
		if !d.InAnyReleasePath(p.Service) { // the ported bugs_open/237 direction
			out = append(out, Violation{Kind: KindNoReleasePath, Service: p.Service, Source: p.Path,
				Detail: fmt.Sprintf("pins %s (a release-built image) but is in no release path", p.Image)})
		}
	}
	return out
}

func InvalidDeployEntries(d Decl, pins []Pin) []Violation {
	haveOverlay := map[string]bool{}
	for _, p := range pins { haveOverlay[p.Service] = true }
	var out []Violation
	for _, e := range d.AgentDeploy {
		if d.HasReleaseImage(e.Image()) { continue }
		out = append(out, Violation{Kind: KindDeployImageUnbuilt, Service: e.Service,
			Detail: fmt.Sprintf("entry %q resolves to image %q, NOT in RELEASE_IMAGES — deploy-agents would retag this overlay to $(IMAGE_TAG) for an image no release builds, and every service sharing that image would ImagePullBackOff together", e.Raw, e.Image())})
	}
	for _, list := range []struct{ name string; entries []Entry }{{"RETAG_EXEMPT", d.RetagExempt}, {"OWN_LINEAGE", d.OwnLineage}} {
		for _, e := range list.entries {
			if haveOverlay[e.Service] { continue }
			out = append(out, Violation{Kind: KindExemptionWithoutOverlay, Service: e.Service,
				Detail: fmt.Sprintf("%s entry %q names a service with no production overlay — it clears nothing today and will silently clear whatever service next takes that name", list.name, e.Raw)})
		}
	}
	return out
}

func TestUncoveredOverlays_BirthOmission(t *testing.T) {
	root := t.TempDir(); baseline(t, root)
	writeOverlay(t, root, "new-check", "overlays/production/uk_001/kustomization.yaml",
		imagesBlock(registry+"/new-check", "v1.0.1300"))
	pins, err := ScanOverlays(root)
	if err != nil { t.Fatalf("ScanOverlays: %v", err) }
	got := Check(mustDecl(t, goodMakefile), pins, registry)
	if !hasKind(got, KindUnbuiltImage, "new-check") {
		t.Fatalf("T1: birth omission NOT caught — the exact shape that fell through eight times; got %v", kinds(got))
	}
	listed := strings.Replace(goodMakefile, "RELEASE_IMAGES := auth-service", "RELEASE_IMAGES := new-check auth-service", 1)
	listed = strings.Replace(listed, "AGENT_DEPLOY_SERVICES := agent-chassis", "AGENT_DEPLOY_SERVICES := new-check agent-chassis", 1)
	if got := Check(mustDecl(t, listed), pins, registry); len(got) != 0 {
		t.Fatalf("T2: compliant tree produced findings %v", kinds(got))
	}
}

func TestInvalidDeployEntries_RunnerImageDropped(t *testing.T) {
	root := t.TempDir(); baseline(t, root)
	writeOverlay(t, root, "github-actions-runner", "overlays/production/uk_001/kustomization.yaml", imagesBlock(registry+"/github-actions-runner", "v1.0.1323"))
	writeOverlay(t, root, "github-actions-runner-vmsites", "overlays/production/uk_001/kustomization.yaml", imagesBlock(registry+"/github-actions-runner", "v1.0.1323"))
	pins, _ := ScanOverlays(root)
	dropped := strings.Replace(goodMakefile, "\tgithub-actions-runner\n", "\n", 1)
	got := Check(mustDecl(t, dropped), pins, registry)
	for _, svc := range []string{"github-actions-runner", "github-actions-runner-vmsites"} {
		if !hasKind(got, KindDeployImageUnbuilt, svc) {
			t.Fatalf("T4: %s not flagged when its image left RELEASE_IMAGES; got %v", svc, kinds(got))
		}
	}
	if got := Check(mustDecl(t, goodMakefile), pins, registry); len(got) != 0 {
		t.Fatalf("T4 control: the compliant runner pair reads as a violation: %v", kinds(got))
	}
}

func TestParseMakefileDecls_MissingBlockIsAnError(t *testing.T) {
	for _, missing := range []string{"RELEASE_IMAGES", "AGENT_DEPLOY_SERVICES", "RETAG_EXEMPT"} {
		src := strings.Replace(goodMakefile, missing+" :=", "SOMETHING_ELSE :=", 1)
		if _, err := ParseMakefileDecls(strings.NewReader(src)); err == nil {
			t.Fatalf("T8: a makefile with no %s parsed clean", missing)
		}
	}
	d, err := ParseMakefileDecls(strings.NewReader(goodMakefile)) // OWN_LINEAGE may be absent
	if err != nil || len(d.OwnLineage) != 0 { t.Fatalf("T8: absent OWN_LINEAGE must be tolerated and empty") }
}

func TestDeclParityWithMake(t *testing.T) {
	root := repoRoot(t)
	if _, err := exec.LookPath("make"); err != nil {
		t.Skip("make not on PATH — SKIPPING the parity check; it is not passing")
	}
	f, err := os.Open(filepath.Join(root, "makefile"))
	if err != nil { t.Fatalf("opening the live makefile: %v", err) }
	defer f.Close()
	parsed, err := ParseMakefileDecls(f)
	if err != nil { t.Fatalf("ParseMakefileDecls on the LIVE makefile: %v", err) }
	cases := []struct{ target string; mine []string }{
		{"print-release-images", parsed.ReleaseImages},
		{"print-agent-deploy-services", rawOf(parsed.AgentDeploy)},
		{"print-retag-exempt", rawOf(parsed.RetagExempt)},
		{"print-own-lineage", rawOf(parsed.OwnLineage)},
	}
	for _, c := range cases {
		theirs, ok := makePrint(t, root, c.target)
		if !ok { continue } // logged as a SKIP, never a silent pass
		if diff := setDiff(c.mine, theirs); diff != "" {
			t.Errorf("%s: this package and make disagree about the live declaration.\n%s", c.target, diff)
		}
	}
}

func TestLiveTreeIsCompliant(t *testing.T) {
	root := repoRoot(t)
	d, pins := mustReadLive(t, root)
	ours := OurPins(pins, "docker.io/aqls")
	if len(ours) == 0 {
		t.Fatal("zero overlays pin one of our images — the scan found nothing, which is not the same as nothing being wrong")
	}
	t.Logf("judged %d overlays pinning our registry, out of %d production overlays", len(ours), len(pins))
	for _, x := range Check(d, pins, "docker.io/aqls") {
		t.Errorf("live tree violation: %s\n    fix: %s", x, x.Remedy)
	}
}

func run(root, registry string, quiet bool) (int, error) {
	mf, err := os.Open(root + "/makefile")
	if err != nil { return exitCannotRun, fmt.Errorf("opening %s/makefile: %w", root, err) }
	defer mf.Close()
	decl, err := releaseset.ParseMakefileDecls(mf)
	if err != nil { return exitCannotRun, err }
	pins, err := releaseset.ScanOverlays(root)
	if err != nil { return exitCannotRun, err }
	ours := releaseset.OurPins(pins, registry)
	if len(ours) == 0 {
		return exitCannotRun, fmt.Errorf("no production overlay pins a %s/ image — either the tree moved or the registry prefix is wrong; refusing to report a clean release from an empty measurement", registry)
	}
	violations := releaseset.Check(decl, pins, registry)
	if len(violations) == 0 {
		fmt.Printf("%sRelease coverage OK%s: %d of %d production overlays pin a %s/ image, and every one is in a release path or explicitly exempt.\n", green, reset, len(ours), len(pins), registry)
		fmt.Printf("%s  Not covered by this check, by construction: services with no overlays/ tree, overlays never applied to the cluster, and whether the tag an image carries matches its contents (BLD-019/BLD-020).%s\n", dim, reset)
		return exitOK, nil
	}
	for _, v := range violations {
		fmt.Fprintf(os.Stderr, "%s  %s%s\n", red, v.String(), reset)
		fmt.Fprintf(os.Stderr, "%s      fix: %s%s\n", yellow, v.Remedy, reset)
	}
	return exitViolation, nil
}

